// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20H { function transferFrom(address, address, uint256) external returns (bool); function transfer(address, uint256) external returns (bool); }
interface AdapterInterface { function relayTokens(address l1Token, address l2Token, uint256 amount, address to) external payable; }

/// Live Across HubPool Sourcify (`0xc186fA914353c44b2E33eBE05f21846F1048bEda`).
/// compilation.name=HubPool. File movers must survive adapter-impl merge.
/// Fixture only — not a finding.
contract HubPool {
    mapping(address => uint256) public pooledTokens;
    AdapterInterface public adapter;

    function addLiquidity(address l1Token, uint256 amount) public payable {
        IERC20H(l1Token).transferFrom(msg.sender, address(this), amount);
        pooledTokens[l1Token] += amount;
    }
    function removeLiquidity(address l1Token, uint256 amountToReturn, bool sendEth) public {
        pooledTokens[l1Token] -= amountToReturn;
        IERC20H(l1Token).transfer(msg.sender, amountToReturn);
        sendEth;
    }
    function proposeRootBundle(uint256[] memory bundleEvaluationBlockNumbers, uint8 poolRebalanceLeafCount, bytes32 poolRebalanceRoot, bytes32 relayerRefundRoot, bytes32 slowRelayRoot) public {
        bundleEvaluationBlockNumbers; poolRebalanceLeafCount; poolRebalanceRoot; relayerRefundRoot; slowRelayRoot;
    }
    function executeRootBundle(uint256 chainId, uint256 groupIndex, uint256[] memory bundleLpFees, int256[] memory netSendAmounts, int256[] memory runningBalances, uint8 leafId, address l1Tokens, bytes32[] memory proof) public {
        chainId; groupIndex; bundleLpFees; netSendAmounts; runningBalances; leafId; l1Tokens; proof;
    }
    function disputeRootBundle() public {}
    function emergencyDeleteProposal() public {}
    function claimProtocolFeesCaptured(address l1Token) public { l1Token; }
}

