// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "../interfaces/AdapterInterface.sol";

/// Etherscan Implementation can be this adapter. After merge, HubPool file movers stay.
contract Ethereum_Adapter is AdapterInterface {
    function relayMessage(address target, bytes calldata message) external payable override { target; message; }
    function relayTokens(address l1Token, address l2Token, uint256 amount, address to) external payable override {
        l1Token; l2Token; amount; to;
    }
}
